update public.institutions set
  feedback_summary_student = 'СамГТУ хвалят за хорошую стипендию, возможности для науки, ухоженные корпуса у набережной и в целом уважительное отношение преподавателей к студентам. Из минусов — слабый контроль деканата за задолженностями и документами, разбросанные по городу корпуса и отдельные жалобы на необъективное занижение оценок бюджетникам.',
  feedback_positive_highlights = '{"хорошая стипендия и возможности для науки","ухоженные корпуса в красивом районе"}',
  feedback_negative_highlights = '{"слабая организация работы деканата с документами","корпуса разбросаны по городу"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Самарский государственный технический университет' and city = 'Самара';

update public.institutions set
  feedback_summary_student = 'ПривГУПС описывают как один из наиболее современных вузов Самары с хорошо оборудованными корпусами, приличными общежитиями и достаточным трудоустройством выпускников по специальности. Критика — перекос в сторону теории при нехватке практики, жалобы на неудобное расположение в Советском районе и на отвлечение студентов от пар ради вузовских мероприятий.',
  feedback_positive_highlights = '{"современная инфраструктура и общежития","трудоустройство выпускников по специальности"}',
  feedback_negative_highlights = '{"перекос в сторону теории, нехватка практики","неудобное расположение кампуса"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Приволжский государственный университет путей сообщения' and city = 'Самара';

update public.institutions set
  feedback_summary_student = 'Отзывы о самарском филиале МГПУ преимущественно положительные: студенты хвалят педагогический состав, благоустроенную территорию, хорошую библиотеку и медиатеку, а также возможности стажировок за рубежом (в том числе в Китае и на Тайване). Явно выраженной системной критики в открытых источниках найти не удалось, что само по себе может говорить о немногочисленности отзывов.',
  feedback_positive_highlights = '{"квалифицированный и отзывчивый педагогический состав","хорошая библиотека и возможности зарубежных стажировок"}',
  feedback_negative_highlights = '{}',
  feedback_based_on_count = 3, feedback_generated_at = now(), updated_at = now()
where name = 'Самарский филиал Московского городского педагогического университета' and city = 'Самара';

update public.institutions set
  feedback_summary_student = 'СГЭУ хвалят за практико-ориентированное обучение, востребованность выпускников-экономистов у самарских работодателей и комфортную инфраструктуру (зоны отдыха, спортзалы, удобное расписание). Критика — часть выпускников считает, что программа не дала достаточных практических знаний, а также жалобы на нестабильные требования преподавателей и отдельных «заваливающих» экзаменаторов.',
  feedback_positive_highlights = '{"практико-ориентированное обучение","востребованность выпускников у работодателей","комфортная инфраструктура кампуса"}',
  feedback_negative_highlights = '{"часть выпускников считает знания недостаточными для работы","нестабильные требования отдельных преподавателей"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Самарский государственный экономический университет' and city = 'Самара';

update public.institutions set
  feedback_summary_student = 'СГИК с полувековой историей готовит востребованных в России и за рубежом специалистов культуры, студенты отмечают качественные постановки и полезные знания от части педагогов. Из критики — отдельные жалобы на бытовые проблемы в общежитиях (перебои с горячей водой) и на ощущение малополезности части учебной программы у некоторых студентов.',
  feedback_positive_highlights = '{"востребованные выпускники в сфере культуры","качественные творческие постановки"}',
  feedback_negative_highlights = '{"бытовые проблемы в общежитиях","часть студентов считает программу малополезной"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Самарский государственный институт культуры' and city = 'Самара';

update public.institutions set
  feedback_summary_student = 'СГСПУ с более чем вековой историей хвалят за хороших преподавателей, доступ к электронной библиотеке и лицензионному ПО, обширную научную и практическую базу (лаборатории, полевые практики), а также лояльное отношение к студентам без жёсткого контроля. Критика — вуз считается популярным, но не престижным (педагогическая специальность не самая востребованная на рынке), также встречаются жалобы на плохую уборку аудиторий и непрозрачность отдельных процессов при поступлении.',
  feedback_positive_highlights = '{"хорошие преподаватели и доступ к учебным ресурсам","обширная научная и практическая база","лояльное отношение к студентам"}',
  feedback_negative_highlights = '{"педагогическая специальность не самая востребованная на рынке","жалобы на плохую уборку аудиторий","непрозрачность отдельных процессов при поступлении"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Самарский государственный социально-педагогический университет' and city = 'Самара';
